package com.estradaplay.comunista;
import android.content.Context;import org.json.*;
final class IncidentStore{private static final String P="epc_incidents_v160",K="rows";static void save(Context c,double lat,double lon,double speed,String hazard,String upcoming,String note){try{JSONArray old=rows(c),out=new JSONArray();JSONObject o=new JSONObject();o.put("at",System.currentTimeMillis());o.put("lat",lat);o.put("lon",lon);o.put("speed",Math.max(0,speed));o.put("hazard",hazard==null?"":hazard);o.put("upcoming",upcoming==null?"":upcoming);o.put("note",note==null?"":note);out.put(o);for(int i=0;i<old.length()&&out.length()<80;i++)out.put(old.opt(i));c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}static JSONArray rows(Context c){try{return new JSONArray(c.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}}
